export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

/* Separate registered parts, so focus can move --field-edge instantly while
   --field-danger still eases. */
@property --field-edge {
  syntax: "<color>";
  inherits: false;
  initial-value: transparent;
}

@property --field-danger {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

@layer components {
  .field {
    display: grid;
    gap: var(--ui-space-2);
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .control {
    --field-height: var(--ui-control-md);
    --reveal-size: var(--ui-control-sm);
    --reveal-inset: calc((var(--field-height) - var(--reveal-size)) / 2);
    position: relative;
    display: grid;
  }

  .field[data-size="lg"] .control {
    --field-height: var(--ui-control-lg);
  }

  .input {
    --field-edge: var(--ui-border-strong);
    --field-edge-width: var(--ui-hairline);
    width: 100%;
    height: var(--ui-control-md);
    /* 14px in, the same as a select's label, so stacked fields line up. */
    padding-inline: calc(var(--reveal-inset) + 10px);
    border: 0;
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--field-edge-width) color-mix(in oklch, var(--field-edge), var(--ui-danger) var(--field-danger));
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
    transition:
      --field-edge var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      --field-danger var(--ui-dur-fast) var(--ui-ease-color);
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
  }

  .field[data-size="lg"] .input {
    height: var(--ui-control-lg);
  }

  .input[data-reveal] {
    padding-inline-end: calc(var(--reveal-size) + var(--reveal-inset) * 2);
  }

  /* Edge draws its own reveal button; one is enough. */
  .input::-ms-reveal {
    display: none;
  }

  .reveal {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: absolute;
    inset-block: var(--reveal-inset);
    inset-inline-end: var(--reveal-inset);
    display: grid;
    place-items: center;
    width: var(--reveal-size);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--reveal-inset));
    background: transparent;
    color: var(--ui-muted);
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @media (hover: hover) {
    .reveal:hover:not(:disabled) {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .reveal:active:not(:disabled) {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .reveal:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .reveal[aria-pressed="true"] {
    color: var(--ui-foreground);
  }

  .reveal:disabled {
    opacity: 0.5;
    cursor: default;
  }

  @media (pointer: coarse) {
    .reveal::before {
      content: "";
      position: absolute;
      inset: calc(var(--reveal-inset) * -1);
    }
  }

  .input::placeholder {
    color: var(--ui-subtle);
  }

  /* Focus fills the field, at once; the edge stays as it rests. */
  .input:focus {
    background: var(--ui-field-focus-fill);
    transition:
      background-color 0s,
      --field-danger var(--ui-dur-fast) var(--ui-ease-color);
  }

  .input[aria-invalid] {
    --field-danger: 100%;
  }

  .input:disabled {
    opacity: 0.5;
    cursor: default;
    transition: none;
  }

  .message {
    display: grid;
    /* Set --field-message-lines when a longer error can arrive, so it never pushes the page. */
    min-height: calc(var(--field-message-lines, 1) * var(--ui-leading-md));
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    /* Hidden after the fade so it also leaves the accessible description. */
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .error[data-shown] .errorText {
    animation: error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .error svg {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    stroke-width: var(--ui-icon-stroke-regular);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    flex-shrink: 0;
  }

  @keyframes error-swap {
    from {
      opacity: 0;
    }
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .input {
      font-size: var(--ui-text-touch);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .error[data-shown] .errorText {
      animation: none;
    }
    .reveal:active:not(:disabled) {
      scale: none;
    }
  }
}

"use client";

import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ComponentProps,
  type FocusEvent,
  type Ref,
} from "react";
import { Icon } from "../icons/icons";
import styles from "./text-field.module.css";

type TextFieldProps = Omit<ComponentProps<"input">, "size"> & {
  label: string;
  /** Guidance shown under the field until there's an error to show instead. */
  hint?: string;
  /** Return a message that says how to fix the value, or null when it's fine. */
  validate?: (value: string) => string | null;
  /** An error from outside, such as the server. Wins over `validate`. */
  error?: string | null;
  size?: "md" | "lg";
};

export function TextField({
  label,
  hint,
  validate,
  error: externalError,
  size = "md",
  className,
  onBlur,
  onChange,
  id,
  type,
  ref,
  ...props
}: TextFieldProps) {
  const fallbackId = useId();
  const inputId = id ?? fallbackId;
  const messageId = `${inputId}-message`;

  // Validate on blur, not mid-typing. Once an error shows, re-check on every
  // keystroke so it clears the moment the value is fixed.
  const [touched, setTouched] = useState(false);
  const [localError, setLocalError] = useState<string | null>(null);
  const error = externalError ?? localError;

  function handleBlur(event: FocusEvent<HTMLInputElement>) {
    setTouched(true);
    setLocalError(validate?.(event.currentTarget.value) ?? null);
    onBlur?.(event);
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    if (touched && localError)
      setLocalError(validate?.(event.currentTarget.value) ?? null);
    onChange?.(event);
  }

  const message = error ?? hint;
  // A line is reserved only when something can show there (even a null error prop).
  const hasMessage = Boolean(hint || validate || externalError !== undefined);

  // The last error stays, faded out, so the slot keeps its height.
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  const password = type === "password";
  const [revealed, setRevealed] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const selection = useRef<[number | null, number | null] | null>(null);

  // Switching the type can drop the caret to the start in some browsers.
  useLayoutEffect(() => {
    const input = inputRef.current;
    const saved = selection.current;
    if (!input || !saved) return;
    selection.current = null;
    if (document.activeElement !== input) return;
    const restore = () => {
      if (document.activeElement === input)
        input.setSelectionRange(saved[0], saved[1]);
    };
    restore();
    // Chrome rebuilds the field's editor after the commit and can reset
    // the caret once more, so restore again on the next frame.
    const frame = requestAnimationFrame(restore);
    return () => cancelAnimationFrame(frame);
  }, [revealed]);

  function toggleReveal() {
    const input = inputRef.current;
    if (input) selection.current = [input.selectionStart, input.selectionEnd];
    setRevealed((r) => !r);
  }

  function setRefs(node: HTMLInputElement | null) {
    inputRef.current = node;
    assignRef(ref, node);
  }

  return (
    <div
      className={className ? `${styles.field} ${className}` : styles.field}
      data-size={size}
    >
      <label className={styles.label} htmlFor={inputId}>
        {label}
      </label>
      <div className={styles.control}>
        <input
          ref={setRefs}
          id={inputId}
          type={password && revealed ? "text" : type}
          className={styles.input}
          data-reveal={password || undefined}
          aria-invalid={error ? true : undefined}
          aria-describedby={hasMessage && message ? messageId : undefined}
          spellCheck={password ? false : undefined}
          autoCapitalize={password ? "off" : undefined}
          autoCorrect={password ? "off" : undefined}
          onBlur={handleBlur}
          onChange={handleChange}
          {...props}
        />
        {password && (
          <button
            type="button"
            className={styles.reveal}
            aria-label="Show password"
            aria-pressed={revealed}
            aria-controls={inputId}
            disabled={props.disabled}
            // Keep focus in the input, so the caret and on-screen keyboard stay put.
            onMouseDown={(event) => {
              if (document.activeElement === inputRef.current)
                event.preventDefault();
            }}
            onClick={toggleReveal}
          >
            <Icon name={revealed ? "eye-off" : "eye"} />
          </button>
        )}
      </div>
      {hasMessage && (
        <>
          {/* The hidden one is visibility: hidden, so it's out of the description and live region. */}
          <p id={messageId} className={styles.message} aria-live="polite">
            {hint && (
              <span className={styles.hint} data-shown={!error || undefined}>
                {hint}
              </span>
            )}
            {lastError && (
              <span
                className={styles.error}
                data-shown={error ? true : undefined}
              >
                <svg viewBox="0 0 16 16" aria-hidden="true">
                  <circle
                    cx="8"
                    cy="8"
                    r="6.25"
                    fill="none"
                    stroke="currentColor"
                  />
                  <path
                    d="M8 4.75v3.75"
                    stroke="currentColor"
                    strokeLinecap="round"
                  />
                  <circle cx="8" cy="11" r="0.9" fill="currentColor" />
                </svg>
                {/* A new message fades in over the old one's place. */}
                <span key={lastError} className={styles.errorText}>
                  {lastError}
                </span>
              </span>
            )}
          </p>
        </>
      )}
    </div>
  );
}

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === "function") ref(value);
  else if (ref) ref.current = value;
}

@layer theme, base, components, utilities;

.lineText {
  composes: wrap from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    container-type: inline-size;
    display: grid;
    /* A card in a conversation, about a message's width. Set
       --agent-question-width to change it. */
    max-inline-size: var(--agent-question-width, 480px);
    grid-template-rows: 1fr;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
  }

  /* Arriving: the space opens, then the card fades up into it, so what's below is pushed, not jumped. */
  .root[data-enter] {
    animation: agent-question-open var(--ui-dur-panel) var(--ui-ease-expand);
  }

  .root[data-enter] .card {
    animation: agent-question-in var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  @keyframes agent-question-open {
    from {
      grid-template-rows: 0fr;
    }
  }

  @keyframes agent-question-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  @keyframes agent-question-fade {
    from {
      opacity: 0;
    }
  }

  .grow {
    min-height: 0;
  }

  .root[data-enter] > .grow {
    animation: agent-question-clip var(--ui-dur-panel);
  }

  @keyframes agent-question-clip {
    from,
    to {
      overflow-y: clip;
    }
  }

  /* ---------- Card ---------- */

  .card {
    display: grid;
    gap: var(--ui-space-4);
    padding: var(--ui-space-4);
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-resting);
  }

  .heading {
    display: grid;
    gap: var(--ui-space-1);
  }

  .eyebrow {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .question {
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    text-wrap: balance;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .question:focus {
    outline: none;
  }

  /* The choices and the field under them. No gap: a closed field leaves none. */
  .body {
    display: grid;
  }

  /* ---------- Choices ---------- */

  .choices {
    display: grid;
    gap: var(--ui-space-2);
  }

  /* Inset by the card's padding, so its corner is the card's less that padding. */
  .choice {
    --choice-pad: var(--ui-space-3);
    --control-size: 16px;
    --choice-edge: var(--ui-border-strong);
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    padding: var(--choice-pad);
    border-radius: calc(var(--ui-radius-lg) - var(--ui-space-4));
    background: transparent;
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--choice-edge);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Chosen: the selected edge and a quiet fill. */
  .choice[data-checked] {
    --choice-edge: var(--ui-field-focus);
    background: var(--ui-fill);
  }

  @media (hover: hover) {
    .choice:hover:not([data-disabled], [data-checked]) {
      --choice-edge: var(--ui-field-focus);
    }
  }

  .choice:active:not([data-disabled]) {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  /* The card draws focus inside its edge, where it can be seen. */
  .choice:has([data-choice]:focus-visible) {
    outline: var(--ui-ring-focus);
    outline-offset: -3px;
  }

  .choice[data-disabled] {
    cursor: default;
  }

  .choice[data-disabled] :is(.control, .text) {
    opacity: 0.5;
  }

  /* Centered on the title's first line. */
  .control {
    position: relative;
    flex-shrink: 0;
    width: var(--control-size);
    height: var(--control-size);
    margin-top: calc((var(--ui-leading-md) - var(--control-size)) / 2);
  }

  /* ----- Radio: as in the radio group ----- */

  .radio {
    --radio-edge: var(--ui-border-strong);
    position: absolute;
    inset: 0;
    display: block;
    border-radius: 50%;
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--radio-edge);
    /* Drives the focus line. */
    color: var(--ui-foreground);
    cursor: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  .choice[data-checked] .radio {
    --radio-edge: var(--ui-accent);
    background: var(--ui-accent);
  }

  .choice:not([data-multiple]) .control::before {
    content: "";
    position: absolute;
    inset: calc((var(--control-size) - 6px) / 2);
    z-index: 1;
    border-radius: 50%;
    background: var(--ui-on-accent);
    clip-path: circle(0 at 50% 50%);
    pointer-events: none;
    transition: clip-path var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .choice:not([data-multiple])[data-checked] .control::before {
    clip-path: circle(50% at 50% 50%);
    transition: clip-path var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* ----- Checkbox: as in the checkbox ----- */

  .box {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-sm) / 2);
    appearance: none;
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    color: var(--ui-foreground);
    cursor: inherit;
    /* Unticking: the fill waits for the mark to un-draw. */
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color) var(--ui-dur-instant),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  .choice[data-checked] .box {
    background: var(--ui-accent);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-accent);
    transition-delay: 0s;
  }

  .mark {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
    fill: none;
    stroke: var(--ui-on-accent);
    stroke-width: var(--ui-icon-stroke);
    stroke-linecap: round;
    stroke-linejoin: round;
    pointer-events: none;
  }

  /* pathLength="1": 0 is drawn, 1.05 is hidden with no round-cap dot left. */
  .mark path {
    stroke-dasharray: 1 2;
    stroke-dashoffset: 1.05;
    transition: stroke-dashoffset var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .choice[data-checked] .mark path {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw);
  }

  /* The card shows focus; the control inside it doesn't again. */
  :is(.radio, .box):focus-visible {
    outline: none;
  }

  /* ----- Text ----- */

  .text {
    display: grid;
    flex: 1;
    gap: 2px;
    min-width: 0;
  }

  .title {
    font-weight: var(--ui-weight-medium);
    overflow-wrap: anywhere;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .description,
  .pick {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .pickLabel {
    color: var(--ui-foreground);
    font-weight: var(--ui-weight-medium);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  /* ---------- Something else ---------- */

  .panel {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    transition:
      grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse),
      opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .panel[data-open="true"] {
    grid-template-rows: 1fr;
    opacity: 1;
    transition:
      grid-template-rows var(--ui-dur-panel) var(--ui-ease-expand),
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  .clip {
    min-height: 0;
    overflow: hidden;
  }

  .other {
    padding-top: var(--ui-space-3);
  }

  /* ---------- Footer ---------- */

  /* The message line and Send share a row: a nudge or an error never moves the button. */
  .footer {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--ui-space-3);
  }

  .message {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .message[data-failed] {
    color: var(--ui-danger-text);
  }

  .messageText {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: var(--ui-space-2);
    align-items: start;
    text-wrap: pretty;
    animation: agent-question-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .message:not([data-failed]) .messageText {
    display: block;
  }

  .messageText > svg {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: 2px;
    color: var(--ui-danger);
  }

  /* ---------- Settled ---------- */

  /* minmax(0, …): the line's unwrapped text mustn't widen the column past the thread. */
  .settled {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .settled[data-enter] {
    animation: agent-question-in var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  .line {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-self: start;
    gap: var(--ui-space-2);
    max-width: calc(100% + 20px);
    min-height: 28px;
    margin-inline: -10px;
    padding: 0 10px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    text-align: start;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .line:hover,
    .line:hover .chevron {
      color: var(--ui-foreground);
    }
  }

  .line:active {
    background: var(--ui-fill);
    color: var(--ui-foreground);
    transition-duration: var(--ui-dur-press);
  }

  .line:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .line {
      min-height: var(--ui-control-md);
    }
  }

  .lineIcon {
    flex-shrink: 0;
    color: var(--ui-foreground);
  }

  .lineLabel {
    font-weight: var(--ui-weight-medium);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  .lineAnswer {
    color: var(--ui-foreground);
  }

  .chevron {
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
    flex-shrink: 0;
    color: var(--ui-muted);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .reopened {
    display: grid;
    gap: var(--ui-space-2);
    padding: var(--ui-space-2) 0 var(--ui-space-1) var(--ui-space-5);
  }

  .quote {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  /* Reduced motion: what moves fades in place instead; heights change in one step. */
  @media (prefers-reduced-motion: reduce) {
    .root[data-enter],
    .root[data-enter] > .grow {
      animation: none;
    }
    .root[data-enter] .card,
    .settled[data-enter],
    .messageText {
      animation-name: agent-question-fade;
    }
    .panel,
    .panel[data-open="true"] {
      transition-property: opacity;
    }
    .choice:not([data-multiple]) .control::before,
    .choice:not([data-multiple])[data-checked] .control::before,
    .mark path,
    .choice[data-checked] .mark path {
      transition: none;
    }
  }
}

"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { Checkbox } from "@base-ui/react/checkbox";
import { CheckboxGroup } from "@base-ui/react/checkbox-group";
import { Radio } from "@base-ui/react/radio";
import { RadioGroup } from "@base-ui/react/radio-group";
import { AnimatedSize } from "../animated-size/animated-size";
import { Button } from "../button/button";
import { Icon } from "../icons/icons";
import { TextField } from "../text-field/text-field";
import styles from "./agent-question.module.css";

// Same path as the checkbox's mark, so a ticked card reads as a ticked box.
const CHECK = "M4.25 8.25L6.75 10.75L11.75 5.25";

export type AgentQuestionChoice = {
  value: string;
  /** A few words: "Private link". */
  title: string;
  /** One line on what it means: "Only people with the link see who’s coming". */
  description?: ReactNode;
  disabled?: boolean;
};

export type AgentQuestionPick = {
  /** The choice the agent would make. */
  value: string;
  /** Why, in a few words: "keeps the guest list private". */
  reason: string;
};

export type AgentQuestionAnswer = {
  /** The chosen choices' values, in the order they're listed. */
  values: string[];
  /** What the person typed under "Something else…", when they chose it. */
  other?: string;
};

export type AgentQuestionStatus = "waiting" | "answered";

type AgentQuestionProps = {
  /** The question, as the agent asks it. Names the group for screen readers. */
  question: string;
  /** Two to four. */
  choices: AgentQuestionChoice[];
  /** The agent's name, as the person knows it. */
  agent?: string;
  /** Checkboxes instead of radios: the person can choose several. */
  multiple?: boolean;
  /** The agent's own pick, marked on its card with the reason. */
  recommended?: AgentQuestionPick;
  /** Adds "Something else…", which opens a short field for a typed answer. */
  allowOther?: boolean;
  /** Placeholder for that field. */
  otherPlaceholder?: string;
  /** Controlled. Set it as soon as `onAnswer` fires (or its promise resolves). */
  status?: AgentQuestionStatus;
  /** With `answered`: what the line shows. Defaults to what was just sent. */
  answer?: AgentQuestionAnswer;
  /** Return a promise to show Send as busy until it settles; a rejection shows an error. */
  onAnswer: (answer: AgentQuestionAnswer) => void | Promise<unknown>;
  /** Default: focus the question only when nothing else on the page has focus. */
  autoFocus?: boolean;
  className?: string;
};

/** The settled line's words: the chosen titles, then the typed answer in quotes. */
function answerText(answer: AgentQuestionAnswer, choices: AgentQuestionChoice[]) {
  const parts = answer.values.map((value) => choices.find((c) => c.value === value)?.title ?? value);
  if (answer.other) parts.push(`“${answer.other}”`);
  return parts.join(", ");
}

/** Opens with height, like the panels in tool approval. */
function Panel({ id, open, children }: { id: string; open: boolean; children: ReactNode }) {
  return (
    <div id={id} className={styles.panel} data-open={open} inert={!open}>
      <div className={styles.clip}>{children}</div>
    </div>
  );
}

/** An agent asking the person to decide something, settling into a line once answered. */
export function AgentQuestion({
  question,
  choices,
  agent = "The agent",
  multiple = false,
  recommended,
  allowOther = false,
  otherPlaceholder = "Type your answer",
  status = "waiting",
  answer: answerProp,
  onAnswer,
  autoFocus,
  className,
}: AgentQuestionProps) {
  const baseId = useId();
  const eyebrowId = `${baseId}-eyebrow`;
  const questionId = `${baseId}-question`;
  const otherPanelId = `${baseId}-other-panel`;
  const reopenId = `${baseId}-reopen`;
  // Can't clash with a caller's value: useId's output has characters values don't.
  const otherValue = `${baseId}-other`;

  const rootRef = useRef<HTMLDivElement>(null);
  const questionRef = useRef<HTMLParagraphElement>(null);
  const lineRef = useRef<HTMLButtonElement>(null);
  const fieldRef = useRef<HTMLInputElement>(null);
  const pointerOnOther = useRef(false);

  const [selected, setSelected] = useState<string[]>([]);
  const [otherText, setOtherText] = useState("");
  const [otherError, setOtherError] = useState<string | null>(null);
  const [nudge, setNudge] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);
  const [sent, setSent] = useState<AgentQuestionAnswer | null>(null);
  const [reopened, setReopened] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  // Only a card that arrives waiting animates in; history doesn't replay.
  const [entering] = useState(status === "waiting");

  const settled = status === "answered";
  const otherOn = selected.includes(otherValue);
  const shown = answerProp ?? sent;
  const answerLine = shown ? answerText(shown, choices) : "";
  const pick = recommended ? choices.find((c) => c.value === recommended.value) : undefined;

  // Say what happened once, when it happens.
  const [previous, setPrevious] = useState(status);
  if (previous !== status) {
    setPrevious(status);
    if (settled) setAnnouncement(answerLine ? `Answer sent: ${answerLine}.` : "Answer sent.");
  }

  // Announced a beat after mount, so the live region exists before it changes.
  useEffect(() => {
    if (!entering) return;
    const id = window.setTimeout(() => setAnnouncement(`${agent} asks: ${question}`), 150);
    const active = document.activeElement;
    // Don't take focus from the prompt or anything else the person is in.
    if (autoFocus ?? (!active || active === document.body)) questionRef.current?.focus({ preventScroll: autoFocus === undefined });
    return () => window.clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The choices are gone once it settles; if focus was in them, it moves to the line.
  const wasSettled = useRef(settled);
  useLayoutEffect(() => {
    if (settled && !wasSettled.current) {
      const active = document.activeElement;
      if (!active || active === document.body || rootRef.current?.contains(active)) lineRef.current?.focus({ preventScroll: true });
    }
    wasSettled.current = settled;
  }, [settled]);

  function choose(next: string[]) {
    if (pending) return;
    // Keep the listed order, whatever order they were ticked in.
    const ordered = [...choices.map((c) => c.value), otherValue].filter((v) => next.includes(v));
    setSelected(ordered);
    setNudge(null);
    if (!ordered.includes(otherValue)) setOtherError(null);
    // A click on "Something else…" means typing next; arrows passing over it don't.
    if (ordered.includes(otherValue) && !selected.includes(otherValue) && pointerOnOther.current) {
      requestAnimationFrame(() => fieldRef.current?.focus());
    }
    pointerOnOther.current = false;
  }

  function send() {
    if (pending) return;
    const text = otherText.trim();
    if (selected.length === 0) {
      setNudge(multiple ? "Choose at least one first." : "Choose one first.");
      return;
    }
    if (otherOn && !text) {
      setOtherError(`Type your answer, or choose one of ${agent}’s.`);
      fieldRef.current?.focus();
      return;
    }
    const answer: AgentQuestionAnswer = {
      values: selected.filter((v) => v !== otherValue),
      ...(otherOn ? { other: text } : {}),
    };
    setFailed(false);
    setSent(answer);
    const result: unknown = onAnswer(answer);
    if (result instanceof Promise) {
      setPending(true);
      result.then(
        () => setPending(false),
        () => {
          setPending(false);
          setFailed(true);
        },
      );
    }
  }

  // Enter sends from a choice or the field. Caught before Base UI sees it, so
  // it never also ticks a box.
  function onKeyDownCapture(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Enter" || event.nativeEvent.isComposing) return;
    const target = event.target as HTMLElement;
    if (target.closest("[data-choice]") || target === fieldRef.current) {
      event.preventDefault();
      event.stopPropagation();
      send();
    }
  }

  // Checkboxes each keep their tab stop; arrows also move between them, as in the radio group.
  function onCheckboxArrows(event: KeyboardEvent<HTMLDivElement>) {
    const step = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[event.key];
    if (!step) return;
    const boxes = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("[data-choice]:not(:disabled)"));
    const i = boxes.indexOf(document.activeElement as HTMLElement);
    if (i === -1) return;
    event.preventDefault();
    boxes[(i + step + boxes.length) % boxes.length]?.focus();
  }

  const all: AgentQuestionChoice[] = allowOther
    ? [...choices, { value: otherValue, title: "Something else…", description: `Tell ${agent} in your own words.` }]
    : choices;

  const cards = all.map((choice) => (
    <ChoiceCard
      key={choice.value}
      choice={choice}
      multiple={multiple}
      checked={selected.includes(choice.value)}
      pick={recommended?.value === choice.value ? recommended.reason : undefined}
      onPointerDown={choice.value === otherValue ? () => (pointerOnOther.current = true) : undefined}
    />
  ));

  const message = failed ? `${agent} didn’t get your answer. Try again.` : nudge;

  return (
    <div
      ref={rootRef}
      className={className ? `${styles.root} ${className}` : styles.root}
      data-status={status}
      data-enter={entering || undefined}
    >
      <div className={styles.grow}>
        <AnimatedSize>
          {settled ? (
            <div key="line" className={styles.settled} data-enter>
              <button
                ref={lineRef}
                type="button"
                className={styles.line}
                aria-expanded={reopened}
                aria-controls={reopenId}
                onClick={() => setReopened((o) => !o)}
              >
                <Icon className={styles.lineIcon} name="check" />
                <span className={styles.lineText}>
                  <span className={styles.lineLabel}>Answer sent</span>
                  {answerLine && <span className={styles.lineAnswer}>: {answerLine}</span>}
                </span>
                <Icon className={styles.chevron} name="chevron-right" data-turn={reopened ? "open" : ""} />
              </button>
              <Panel id={reopenId} open={reopened}>
                <div className={styles.reopened}>
                  <p className={styles.quote}>
                    {agent} asked: “{question}”
                  </p>
                  {pick && recommended && (
                    <p className={styles.quote}>
                      {agent} recommended {pick.title}: {recommended.reason}
                    </p>
                  )}
                </div>
              </Panel>
            </div>
          ) : (
            <div
              key="card"
              className={styles.card}
              role="group"
              aria-labelledby={`${eyebrowId} ${questionId}`}
              onKeyDownCapture={onKeyDownCapture}
            >
              <div className={styles.heading}>
                <span id={eyebrowId} className={styles.eyebrow}>
                  {agent} asks
                </span>
                <p ref={questionRef} id={questionId} className={styles.question} tabIndex={-1}>
                  {question}
                </p>
              </div>

              <div className={styles.body}>
                {multiple ? (
                  <CheckboxGroup
                    value={selected}
                    onValueChange={(next) => choose(next)}
                    role="group"
                    aria-labelledby={questionId}
                    aria-busy={pending || undefined}
                    className={styles.choices}
                    onKeyDown={onCheckboxArrows}
                  >
                    {cards}
                  </CheckboxGroup>
                ) : (
                  <RadioGroup<string>
                    value={selected[0] ?? ""}
                    onValueChange={(next) => choose([next])}
                    aria-labelledby={questionId}
                    aria-busy={pending || undefined}
                    className={styles.choices}
                  >
                    {cards}
                  </RadioGroup>
                )}

                {allowOther && (
                  <Panel id={otherPanelId} open={otherOn}>
                    <div className={styles.other}>
                      <TextField
                        ref={fieldRef}
                        label="Your answer"
                        hint={`Enter sends it to ${agent}.`}
                        placeholder={otherPlaceholder}
                        maxLength={200}
                        autoComplete="off"
                        value={otherText}
                        error={otherError}
                        onChange={(e) => {
                          setOtherText(e.currentTarget.value);
                          if (otherError && e.currentTarget.value.trim()) setOtherError(null);
                        }}
                      />
                    </div>
                  </Panel>
                )}
              </div>

              <div className={styles.footer}>
                <p className={styles.message} data-failed={failed || undefined} aria-live="polite">
                  {message && (
                    <span key={message} className={styles.messageText}>
                      {failed && <Icon name="alert" />}
                      {message}
                    </span>
                  )}
                </p>
                <Button busy={pending} onClick={send}>
                  Send
                </Button>
              </div>
            </div>
          )}
        </AnimatedSize>
      </div>

      <span role="status" className={styles.srOnly}>
        {announcement}
      </span>
    </div>
  );
}

function ChoiceCard({
  choice,
  multiple,
  checked,
  pick,
  onPointerDown,
}: {
  choice: AgentQuestionChoice;
  multiple: boolean;
  checked: boolean;
  pick?: string;
  onPointerDown?: () => void;
}) {
  const id = useId();
  const titleId = `${id}-title`;
  const describedBy =
    [choice.description ? `${id}-description` : null, pick ? `${id}-pick` : null].filter(Boolean).join(" ") || undefined;

  return (
    <label
      className={styles.choice}
      data-checked={checked || undefined}
      data-disabled={choice.disabled || undefined}
      data-multiple={multiple || undefined}
      onPointerDown={onPointerDown}
    >
      <span className={styles.control}>
        {multiple ? (
          <>
            <Checkbox.Root
              // A native button, so the wrapping label lands on the control itself.
              nativeButton
              render={<button type="button" />}
              value={choice.value}
              disabled={choice.disabled}
              className={styles.box}
              aria-labelledby={titleId}
              aria-describedby={describedBy}
              data-choice=""
            />
            <svg className={styles.mark} viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
              <path d={CHECK} pathLength={1} />
            </svg>
          </>
        ) : (
          <Radio.Root
            value={choice.value}
            disabled={choice.disabled}
            className={styles.radio}
            aria-labelledby={titleId}
            aria-describedby={describedBy}
            data-choice=""
          />
        )}
      </span>
      <span className={styles.text}>
        <span id={titleId} className={styles.title}>
          {choice.title}
        </span>
        {choice.description && (
          <span id={`${id}-description`} className={styles.description}>
            {choice.description}
          </span>
        )}
        {pick && (
          <span id={`${id}-pick`} className={styles.pick}>
            <span className={styles.pickLabel}>Recommended:</span> {pick}
          </span>
        )}
      </span>
    </label>
  );
}
